type Apify = { token: string };

// Gets Google positions (top 100) of your domain for each keyword from the Google SERP API Actor on Apify.
// Pay per result on Apify: $0.003 per Google results page (top 100 = $0.03 per keyword). Built and sold by Rowfeed.
export async function main(apify: Apify, keywords: string[], domain: string, location = "United States", language = "English") {
  const body = { queries: keywords, targetDomain: domain, location, language, device: "desktop", resultsPerQuery: 100 };
  const r = await fetch("https://api.apify.com/v2/acts/rowfeed~google-serp-api/run-sync-get-dataset-items?clean=1&maxTotalChargeUsd=2", {
    method: "POST",
    headers: { Authorization: `Bearer ${apify.token}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!r.ok) throw new Error(`Apify returned HTTP ${r.status}: ${(await r.text()).slice(0, 300)}`);
  return await r.json();
}

import * as wmill from "windmill-client";

// Compares this run with the previous run (stored in Windmill state) and builds a week-over-week rank report.
export async function main(rows: any[], domain: string) {
  let prev: Record<string, number | null> = {};
  try { prev = ((await wmill.getState()) ?? {}) as Record<string, number | null>; } catch { prev = {}; }
  const now: Record<string, number | null> = {};
  const errors = rows.filter((r) => r.error).map((r) => `${r.query ?? r.keyword}: ${r.errorMessage}`);
  const report = rows.filter((r) => !r.error).map((r) => {
    const pos: number | null = r.target_position ?? null;
    now[r.query] = pos;
    const before = prev[r.query];
    let change = "first check";
    if (before !== undefined) {
      if (pos === null && before === null) change = "still not in top 100";
      else if (pos === null) change = `dropped out (was ${before})`;
      else if (before === null) change = "entered the top 100";
      else if (before > pos) change = `up ${before - pos}`;
      else if (before < pos) change = `down ${pos - before}`;
      else change = "no change";
    }
    return { keyword: r.query, position: pos, previous: before ?? null, change, ranking_url: r.target_url ?? null };
  });
  try { await wmill.setState({ ...prev, ...now }); } catch { /* manual runs without state still return the report */ }
  const lines = report.map((x) => `${x.keyword}: ${x.position ?? "not in top 100"} (${x.change})`);
  return { domain, checked_at: new Date().toISOString(), summary: lines.join("\n"), report, errors };
}
